add_filter( 'woocommerce_return_to_shop_redirect', 'perfectpixel_return_to_shop_url' );

function perfectpixel_return_to_shop_url( $url ) {
	$custom = trim( '{{return_to_shop_url}}' );
	if ( '' === $custom ) {
		return home_url( '/' );
	}
	return 0 === strpos( $custom, '/' ) ? home_url( $custom ) : $custom;
}
